) VALUES
  ('prod-tangerine-dream', 'Tangerine Dream', 'Craft Medical Flower • Uplifting Citrus', 'flower', 'Craft Flower', 'Sativa', 180, 220, 4.8, 42, '17.00-23.00%', '0.00-1.00%', '["Myrcene","Limonene","Caryophyllene"]', '["Euphoric","Creative","Energy","Clarity"]', '["Stress Relief","Chronic Fatigue","Mild Depression","Daytime Focus"]', 'Award-winning sativa-dominant hybrid renowned for its sweet citrus aroma and invigorating cerebral clarity. Hand-trimmed and cold-cured for 28 days to preserve delicate terpene profiles.', 'Start with 0.1g vaporization or gentle inhalation. Optimal daytime relief without lethargy.', 12, 5, 1, 1, 1, 1, 'Popular', 'Oct 2026', 'HH-ZA-TD882', '/assets/aistudio/Screenshot_2026-10-28_at_13-21-08_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_9c338267.png', 'from-amber-100 to-emerald-100'),
  ('prod-high-cbd-50-oil', 'High CBD 50 Oil', 'Full-Spectrum Organic Tincture (1500mg)', 'tinctures', 'CBD Tinctures', 'CBD-Rich', 340, 420, 4.9, 88, '0.05-0.20%', '15.00-18.50%', '["Beta-Caryophyllene","Linalool","Humulene"]', '["Calm","Restoration","Anti-Inflammatory","Physical Ease"]', '["Arthritis & Joint Pain","Anxiety","Sleep Disruption","Neuropathic Relief"]', 'Cold-pressed MCT-infused medical CBD drops crafted from sun-grown South African hemp. Supercritical CO2 extracted without harsh hydrocarbons, delivering holistic entourage relief.', '0.5ml (approx. 25mg CBD) sublingually under tongue for 60 seconds twice daily.', 12, 5, 1, 1, 1, 1, 'Sale', 'Sep 2026', 'HH-ZA-CBD50-09', '/assets/aistudio/Screenshot_2026-10-28_at_13-21-08_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_9c338267.png', 'from-emerald-100 to-teal-100'),
  ('prod-purple-hawaiian-haze', 'Purple Hawaiian Haze', 'Feminized Exotic Seeds (5 Pack)', 'seeds', 'Medicinal Seeds', 'Sativa', 290, 350, 5, 31, '18.50-24.00%', '0.20-0.80%', '["Terpinolene","Myrcene","Pinene"]', '["Uplifting","Focus","Blissful","Head Clarity"]', '["Brain Fog","Appetite Stimulation","Social Ease","Fatigue"]', 'Rare tropical sativa lineage bred for vigorous outdoor and greenhouse growth in South African climates. Yields deeply fragrant violet-tinted flowers rich in exotic terpenes.', 'Germination rate verified > 96%. Indoor flower 9-10 weeks; outdoor harvest April.', 12, 5, 1, 1, 0, 0, 'Featured', 'Oct 2026', 'HH-SEED-PHH-44', '/assets/aistudio/Screenshot_2026-10-28_at_13-20-55_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_cfa9b507.png', 'from-purple-100 to-emerald-100'),
  ('prod-durban-poison-feminized', 'Durban Poison Heirloom', 'Pure South African Landrace Seeds (5 Pack)', 'seeds', 'Medicinal Seeds', 'Sativa', 260, 310, 4.9, 64, '19.00-25.00%', '0.10-0.50%', '["Terpinolene","Ocimene","Myrcene"]', '["Clear High","Pure Energy","Productivity","Alertness"]', '["ADHD/Focus","Chronic Migraines","Depression","Chronic Fatigue"]', 'The world-famous KwaZulu-Natal native heirloom strain. Preserved in its purest genetic form with sweet liquorice aroma, soaring energetic onset, and remarkable mold resilience.', 'Germinates rapidly within 48-72 hours. Perfect for outdoor sun growers across South Africa.', 12, 5, 1, 1, 0, 1, 'SA Heritage', 'Oct 2026', 'HH-ZA-DP01', '/assets/aistudio/Screenshot_2026-10-28_at_13-20-55_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_cfa9b507.png', 'from-amber-100 to-lime-100'),
  ('prod-granddaddy-purple-indica', 'Granddaddy Purple', 'Dense Nighttime Indica Flower', 'flower', 'Craft Flower', 'Indica', 195, 240, 4.8, 53, '20.00-24.00%', '0.10-0.40%', '["Myrcene","Caryophyllene","Pinene"]', '["Deep Relaxation","Body Melt","Peace","Sedation"]', '["Insomnia","Chronic Pain","Muscle Spasms","Restless Legs"]', 'Legendary California cross of Purple Urkle and Big Bud. Expresses deep berry and grape aromatics with immediate physical relaxation ideal for evening pain relief.', 'Recommended for night-time administration approximately 45 minutes before sleep.', 12, 5, 1, 1, 0, 0, NULL, 'Oct 2026', 'HH-ZA-GDP201', '/assets/aistudio/Screenshot_2026-10-28_at_13-21-08_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_9c338267.png', 'from-indigo-100 to-violet-100'),
  ('prod-cannatonic-recovery-balm', 'Cannatonic Botanical Recovery Balm', 'Arnica & CBD Deep Tissue Salve (100ml)', 'topicals', 'Therapeutic Topicals', 'CBD-Rich', 275, 320, 4.9, 37, '0.00%', '1000mg Isolate', '["Eucalyptus","Menthol","Linalool"]', '["Localized Relief","Cooling","Anti-Inflammatory"]', '["Joint Stiffness","Post-Workout Soreness","Bruising","Eczema / Dry Skin"]', 'Handcrafted with organic Cape shea butter, wild fynbos beeswax, arnica montana, and pure laboratory-grade CBD. Penetrates swiftly without greasy residue.', 'Massage a dime-sized amount directly onto affected muscle or joint areas up to 3-4 times daily.', 12, 5, 1, 1, 0, 0, 'Organic', 'Sep 2026', 'HH-TOP-883', '/assets/aistudio/Screenshot_2026-10-28_at_13-21-08_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_9c338267.png', 'from-emerald-100 to-amber-100'),
  ('prod-honey-cannabis-gummies', 'Karoo Honey CBD Gummies', '30 Vegan Fruit Pectins (25mg each)', 'edibles', 'Wellness Edibles', 'CBD-Rich', 240, 280, 4.7, 49, '0.00%', '750mg Total', '["Limonene","Myrcene"]', '["Mild Calm","Stress Buffering","Sustained Equilibrium"]', '["Workplace Tension","Social Unease","Daily General Wellness"]', 'Crafted with genuine raw Karoo honey, real raspberry juice, and pure water-soluble CBD for 4x enhanced bioavailability compared to traditional oils.', 'Consume 1 gummy daily in morning or mid-afternoon. Chew thoroughly before swallowing.', 12, 5, 1, 1, 1, 0, 'Vegan', 'Oct 2026', 'HH-EDB-091', '/assets/aistudio/Screenshot_2026-10-28_at_13-21-08_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_9c338267.png', 'from-amber-100 to-rose-100'),
  ('prod-live-rosin-durban', 'Live Rosin Durban Gold', 'Solventless Cold-Cure Extract (1g)', 'concentrates', 'Pure Concentrates', 'Sativa', 450, 520, 5, 28, '74.50-79.00%', '1.20-2.40%', '["Terpinolene","Humulene","Caryophyllene"]', '["Potent Clarity","Clean Elevation","Intense Terpene Bouquet"]', '["Acute Severe Pain","Chemotherapy Nausea","Intense Anxiety"]', 'First wash, 73u-120u fresh frozen ice water bubble hash pressed under low heat. Zero chemical solvents, preserving 100% of the live plant terpene fingerprint.', 'Ultra-concentrated. Micro-dose a grain-of-rice sized amount via compatible concentrate vaporizer.', 3, 5, 1, 1, 0, 0, 'Connoisseur', 'Oct 2026', 'HH-EXT-LR02', '/assets/aistudio/Screenshot_2026-10-28_at_13-21-08_Herbalist___Medical_Marijuana_Store_Website_Template_Preview_-_ThemeForest_9c338267.png', 'from-yellow-100 to-amber-200')
